// Provider marks for ProviderMark: each provider's own mark, never a drawn lookalike. Every shape is its source's path,
// unchanged and in one colour (the text colour, so it follows the theme and every highlight); only the view is set here:
// it cuts the source's grid to the mark and pads it so every mark reads at one optical size, centred in its box. Each
// mark names its source and licence (THIRD-PARTY-NOTICES.md at the repository root lists the sources). The marks are
// trademarks of their owners, used only to name the provider. Hoody AI never takes a mark from here: ProviderMark draws
// the Hoody icon for it. A provider with no mark here draws its Monogram (ProviderMark.logos.test.tsx accounts for every
// catalogue provider either way).

export interface LogoPath {
  d: string;
  /** The source draws this shape with fill-rule evenodd. */
  evenodd?: true;
  /** The source's fill-opacity for this shape (a second tone of the one colour). */
  opacity?: number;
}

export interface ProviderLogo {
  /** The SVG viewBox: the source's grid, cut to the mark and padded to one optical size. */
  view: string;
  paths: readonly LogoPath[];
}

