/** The mark of a built-in provider, or undefined (ProviderMark then draws the Monogram). */
export function providerLogo(id: string): ProviderLogo | undefined {
  return Object.hasOwn(BY_ID, id) ? BY_ID[id] : undefined;
}

/** Every provider id with a mark (for tests). */
export function providerLogoIds(): readonly string[] {
  return Object.keys(BY_ID);
}
